<header class="page-heading"><div><h1>Lists</h1><p>Keep related captures together.</p></div></header>
<section class="list-create"><form class="inline-form" method="post" action="/lists"><input type="hidden" name="_csrf" value="<?=htmlspecialchars($csrf)?>"><label>New list<input name="title" maxlength="160" required autocomplete="off" placeholder="Reading list"></label><button class="button button-primary">Create list</button></form></section>
<section class="list-grid" aria-label="Lists"><?php if (!$lists): ?><div class="empty-state"><h2>No lists yet</h2><p>Create a list, then add captures from their detail view.</p></div><?php endif; ?><?php foreach ($lists as $list): ?><article class="list-card"><a class="list-card-main" href="<?=htmlspecialchars($list['url'])?>"><span class="list-card-count"><?=(int)$list['capture_count']?> <?=((int)$list['capture_count']) === 1 ? 'item' : 'items'?></span><h2><?=htmlspecialchars($list['title'])?></h2><p><?=htmlspecialchars(mb_strimwidth((string)($list['top_capture_title'] ?? 'No captures yet'), 0, 90, '…'))?></p></a><div class="list-card-actions"><a href="/lists/<?=rawurlencode($list['id'] . '-' . $list['slug'])?>/edit">Edit</a><form method="post" action="/lists/<?=rawurlencode($list['id'] . '-' . $list['slug'])?>/delete" onsubmit="return confirm('Delete this list? Captures will be kept.')"><input type="hidden" name="_csrf" value="<?=htmlspecialchars($csrf)?>"><button class="button button-danger-outline">Delete</button></form></div></article><?php endforeach; ?></section>
